mapper.select:


    del_flag = '0'
     AND process_code LIKE CONCAT('%', #{process_code}, '%')
     AND process_name LIKE CONCAT('%', #{process_name}, '%')
     AND process_type = #{process_type}
     AND status = #{status}
     AND workshop_name LIKE CONCAT('%', #{workshop_name}, '%')
     AND line_name LIKE CONCAT('%', #{line_name}, '%')
     AND is_key_process = #{is_key_process}
     AND is_outsource = #{is_outsource}
     AND date(create_time) >= #{params.beginTime}
     AND date(create_time) <= #{params.endTime}

ORDER BY process_id DESC
